// scripts/ingest/lib/minted.ts
var writerOwns = (mintedBy, writer) => mintedBy === writer;
var staleOwnRows = (existing, payloadNumbers, writer, ceiling) => {
  const carried = new Set(payloadNumbers);
  return existing.filter((r) => r.number <= ceiling && writerOwns(r.minted_by, writer) && !carried.has(r.number));
};
async function syncMintedRows(seriesId, rows, writer, ceiling) {
  const { db: db2, selectAll: selectAll2 } = await Promise.resolve().then(() => (init_db(), db_exports));
  const stamped = rows.map((r) => ({ ...r, series_id: seriesId, minted_by: writer }));
  for (let i = 0; i < stamped.length; i += 500) {
    const { error } = await db2.from("episodes").upsert(stamped.slice(i, i + 500), { onConflict: "series_id,number" });
    if (error) throw new Error(`episodes upsert (${seriesId}, ${writer}): ${error.message}`);
  }
  const top = ceiling ?? rows.reduce((m, r) => Math.max(m, r.number), 0);
  const existing = await selectAll2("episodes", "number, minted_by", (q) => q.eq("series_id", seriesId).lte("number", top));
  const stale = staleOwnRows(existing, rows.map((r) => r.number), writer, top);
  if (stale.length) {
    const { error } = await db2.from("episodes").delete().eq("series_id", seriesId).eq("minted_by", writer).in("number", stale.map((r) => r.number));
    if (error) throw new Error(`episodes stale delete (${seriesId}, ${writer}): ${error.message}`);
  }
  return { upserted: stamped.length, deleted: stale.length };
}

